fortgesetzte_guetergemeinschaft_altlasten <- function(persoenliche_altverbindlichkeiten=NULL,altverbindlichkeiten_erbendeckung=NULL,ersatzpflicht_zum_gesamtgut=NULL,ersatzpflicht_erbendeckung=NULL,zuordnungsnachweis=NULL) {
  schuld <- .geld(persoenliche_altverbindlichkeiten);schulddeckung <- .geld(altverbindlichkeiten_erbendeckung)
  ersatz <- .geld(ersatzpflicht_zum_gesamtgut);ersatzdeckung <- .geld(ersatzpflicht_erbendeckung)
  .text(zuordnungsnachweis,"zuordnungsnachweis")
  if (.vergleichen(schulddeckung,schuld)>0 || .vergleichen(ersatzdeckung,ersatz)>0) .fehler("EINGABE_UNGUELTIG","Erbendeckung darf den jeweils zugeordneten Ausgangsposten nicht \u00fcbersteigen.")
  schuldrest <- .subtrahieren(schuld,schulddeckung);ersatzrest <- .subtrahieren(ersatz,ersatzdeckung)
  eingaben <- list(persoenliche_altverbindlichkeiten=persoenliche_altverbindlichkeiten,altverbindlichkeiten_erbendeckung=altverbindlichkeiten_erbendeckung,ersatzpflicht_zum_gesamtgut=ersatzpflicht_zum_gesamtgut,ersatzpflicht_erbendeckung=ersatzpflicht_erbendeckung,zuordnungsnachweis=zuordnungsnachweis)
  ergebnis <- .ergebnis(list(ungedeckte_altverbindlichkeiten=.bruchteile(schuldrest),ungedeckte_ersatzpflicht=.bruchteile(ersatzrest),anrechnungspostensumme=.bruchteile(.addieren(schuldrest,ersatzrest))),"EUR","BGB_FORTGESETZTE_GUETERGEMEINSCHAFT_ALTLASTEN",eingaben,list(list(operation="Jeweils zugeordnete Erbendeckung abziehen und ungedeckte Altverbindlichkeiten sowie Ersatzpflicht addieren.")),eingaben)
  ergebnis$hinweise <- list("\u00a71500I/II: reine Ermittlung der ungedeckten Anrechnungsposten vor der Auseinandersetzungsbilanz. Ausgangsposten rechtlich getrennt und ohne \u00dcberschneidung: pers\u00f6nliche Verbindlichkeiten des Verstorbenen im Innenverh\u00e4ltnis sowie dessen Ersatzpflicht zum Gesamtgut. Erbendeckung umfasst die rechtlich erlangbare Deckung, nicht lediglich bisher tats\u00e4chlich eingegangene Zahlung; deren Uneinbringlichkeit/Erreichbarkeit ist qualifiziert. Keine doppelte Deckungszuordnung. Nicht bereits bereinigte Restposten nochmals vermindern. Kein zus\u00e4tzlicher Geldanspruch gegen Abk\u00f6mmlinge und keine individuelle Verteilung; nach\u00a71498 besteht die \u00fcberschie\u00dfende pers\u00f6nliche Ersatzpflicht des\u00a71476II2 nur f\u00fcr den \u00fcberlebenden Ehegatten. Gesamtgutsbereinigung, Einrechnung vor Halbteilung, Anrechnung auf die Abk\u00f6mmlingsh\u00e4lfte sowie\u00a71501/1503 sind nachgelagerte Bilanzschritte, hier nicht als vollst\u00e4ndige Teilung ausgegeben.")
  ergebnis
}
